    def handle_endtag(self, tag):
        if tag in ('h1','h2','h3','h4'):
            self.in_heading = False
            self.out.append('\n')
        elif tag == 'pre':
            self.in_pre = False
            self.out.append('\n```\n')
        elif tag == 'code':
            self.in_code = False
        elif tag == 'table':
            self.in_table = False
            # render table as markdown
            if self.table_rows:
                header = self.table_rows[0]
                self.out.append('\n' + ' | '.join(header) + '\n')
                self.out.append(' | '.join(['---']*len(header)) + '\n')
                for row in self.table_rows[1:]:
                    self.out.append(' | '.join(row) + '\n')
                self.out.append('\n')
        elif tag == 'tr' and self.in_table:
            self.in_tr = False
            if self.current_row:
                self.table_rows.append([c.strip() for c in self.current_row])
        elif tag == 'th' and self.in_table:
            self.in_th = False
        elif tag == 'td' and self.in_table:
            self.in_td = False

    def handle_data(self, data):
        text = data.strip()
        if not text:
            return
        if self.in_heading:
            level = self.heading_level or 2
            self.out.append('\n' + ('#'*level) + ' ' + text + '\n')
        elif self.in_table:
            if self.in_th or self.in_td:
                self.current_row.append(text)
        elif self.in_pre:
            self.out.append(data)
        elif self.in_code:
            self.out.append('`' + text + '`')
        else:
            self.out.append(text + '\n')

